	if err != nil {
		t.Skipf("cannot open %s: %v", os.DevNull, err)
	}
	defer devnull.Close()
	if caps := DetectCapsWithEnv(devnull, envFrom(map[string]string{"TERM": "xterm-256color"})); caps != PlainCaps() {
