func TestFactsVectorRankedRepairsInvalidCachedVector(t *testing.T) {
	dir := t.TempDir()
	fact := factRecord{ID: "fact:repair", Text: "durable checkpoint policy", Status: factStatusActive}
	e := &fakeFusionEmbedder{vecs: map[string][]float32{
